pair V=(0,h);
real yc=h*(1-k);
real t0=degrees(asin(0.15));
draw(scale(3,0.6)*arc((0,0),1,t0,180-t0),dashed);draw(scale(3,0.6)*arc((0,0),1,180-t0,360+t0),linewidth(0.9));
draw(shift(0,yc)*scale(3k,0.6k)*arc((0,0),1,t0,180-t0),dashed);
