defaultpen(fontsize(10pt));
real c=3*cos(40*pi/180), s=3*sin(40*pi/180);
pair Cc=(0,0),B=(c,0),A=(c,s);
draw(Cc--B--A--cycle,linewidth(0.9));
draw((c-0.2,0)--(c-0.2,0.2)--(c,0.2));
draw(arc(Cc,0.55,0,40));label("$40^\circ$",Cc+0.95*dir(20));
