for(int i=0;i<4;++i){
  pair K=rotate(90*i)*(1,1);
  path seg=arc(K,1,180+90*i,270+90*i)--cycle;
  fill(seg,rgb(0.8,0.88,1));
  draw(arc(K,1,180+90*i,270+90*i),linewidth(0.7));
}
draw((1,0)--(0,1)--(-1,0)--(0,-1)--cycle,dashed);
draw((-1,-1)--(1,-1)--(1,1)--(-1,1)--cycle,linewidth(0.9));
dot(O);label("$O$",O,S);
label("$(1,1)$",(1,1),NE);label("$(-1,1)$",(-1,1),NW);label("$(-1,-1)$",(-1,-1),SW);label("$(1,-1)$",(1,-1),SE);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Each segment has area (quarter disc minus right triangle) $\dfrac{\pi}{4}-\dfrac{1}{2}$, and the four segments (shaded) do not overlap. The probability is
\[
\dfrac{4\left(\dfrac{\pi}{4}-\dfrac{1}{2}\right)}{4}=\dfrac{\pi-2}{4},
\]
answer $\boxed{\textbf{(B)}}$.

