pair A=(1.6,5),B=(0,0),C=(7,0);
pair Ep=A+(B-A)/3,F=(A+C)/2;
fill(A--Ep--F--cycle,palegray);
draw(A--B--C--cycle,linewidth(0.9));
draw(Ep--F,linewidth(0.8));
dot(Ep);dot(F);
label("$A$",A,N);label("$B$",B,SW);label("$C$",C,SE);
label("$E$",Ep,W);label("$F$",F,NE);
label("$1$",(A+Ep)/2,W);label("$2$",(Ep+B)/2,W);
label("$1$",(A+F)/2,NE);label("$1$",(F+C)/2,NE);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Hence $[AEF]=\dfrac{72}{6}=\boxed{12}$.

The graph of $f$ passes through $(-3,-10)$ and $(3,8)$, so its slope is $\dfrac{8-(-10)}{3-(-3)}=\dfrac{18}{6}=3$. Perpendicular lines (neither vertical) have slopes with product $-1$, so the graph of $g$ has slope $-\dfrac{1}{3}$ and passes through $(-3,-10)$:
\[
g(x)=-10-\dfrac{1}{3}(x+3).
\]

