label("$21$",(A+B)/2,NW);label("$26$",(B+C)/2,NE);label("$32$",(C+D)/2,SE);label("$\sqrt{789}$",(A+D)/2,SW);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Hence $AB^2+CD^2=p^2+b^2+q^2+d^2=BC^2+DA^2$, and
\[
AD^2=21^2+32^2-26^2=441+1024-676=789,\qquad AD=\boxed{\sqrt{789}}.
\]
(The figure uses $b=12$, $p=\sqrt{297}$, $q=\sqrt{532}$, $d=\sqrt{492}$, which fit the data.)

Both points lie above the line $y=x$. Reflect the start $(-1,4)$ in the line $y=x$ to get $(4,-1)$. For any point $X$ on the line, the distance from $(-1,4)$ to $X$ equals the distance from $(4,-1)$ to $X$, so the route length is at least the straight distance from $(4,-1)$ to $(12,21)$, with equality when $X$ lies on that segment:

\begin{asy}
usepackage("amsmath");
